/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.6.1/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    id("org.openjfx.javafxplugin") version "0.1.0"
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit test framework.
    testImplementation(libs.junit)

    // This dependency is used by the application.
    implementation(libs.guava)

    // Source: https://mvnrepository.com/artifact/tools.jackson.core/jackson-databind
    implementation("tools.jackson.core:jackson-databind:3.2.4")
}

javafx {
    version = "26"
    modules = listOf("javafx.controls", "javafx.fxml")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

application {
    // Define the main class for the application.
    mainClass = "org.autotest.Launcher"
}

tasks.register("runfx") {
    group = "application"
    description = "Runs the application with the JavaFX runtime configured by the JavaFX plugin."
    dependsOn(tasks.named("run"))
}

tasks.register<Jar>("fatjar") {
    group = "build"
    description = "Builds an executable JAR containing the application and its runtime dependencies."
    archiveClassifier.set("all")
    dependsOn(tasks.named("classes"))

    manifest {
        attributes["Main-Class"] = "org.autotest.Launcher"
    }

    duplicatesStrategy = org.gradle.api.file.DuplicatesStrategy.EXCLUDE
    from(sourceSets.main.get().output)
    from({
        configurations.runtimeClasspath.get().map { dependency ->
            if (dependency.isDirectory) dependency else zipTree(dependency)
        }
    })

    exclude("META-INF/*.SF", "META-INF/*.DSA", "META-INF/*.RSA", "META-INF/INDEX.LIST")
    exclude("module-info.class", "META-INF/versions/**/module-info.class")
}
